   491|    const createRes = await fetch(`https://api.github.com/repos/${repo}/git/refs`, {
   492|      method: 'POST',
   493|      headers: ledgerGithubHeaders(),
   494|      body: JSON.stringify({ ref: `refs/heads/${LEDGER_GITHUB_BRANCH}`, sha: baseSha }),
