   512|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   513|    );
   514|    if (currentRes.ok) {
   515|      const current = await currentRes.json() as { sha?: string };
   516|      existingSha = current.sha;
   517|    }
   518|    const putRes = await fetch(
   519|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}`,
