   540|  // separate completed development tasks. A duplicate fingerprint (same
   541|  // commitSha + deployId + filesChanged + finalStatus) is logged but the entry
   542|  // is still recorded (marked as duplicate) so the ledger is complete.
   543|  const fingerprint = fingerprintEvidence({
   544|    commitSha: result.commitSha,
   545|    deployId: result.deployId,
   546|    filesChanged: result.changedFiles,
   547|    finalStatus: result.finalStatus,
   548|  });
   549|  result.evidenceFingerprint = fingerprint;
   550|  const current = await loadLedger();
   551|  const priorMatch = current.entries.find((e) => e.evidenceFingerprint === fingerprint && e.jobId !== result.jobId);
   552|  if (priorMatch) {
   553|    appendDurableEvent(LEDGER_FILE, { type: 'duplicate_evidence_rejected', jobId: result.jobId, priorJobId: priorMatch.jobId, fingerprint }).catch(() => {});
   554|  }
   555|  const entries = [result, ...current.entries.filter((e) => e.jobId !== result.jobId)].slice(0, MAX_LEDGER_RETAINED);
