   557|    marker: IVX_SENIOR_DEV_WORKER_MARKER,
   558|    durable: isDurableStoreConfigured(),
   559|    updatedAt: nowIso(),
   560|    entries,
   561|  };
   562|  memoryLedger = doc;
   563|  if (isDurableStoreConfigured()) {
   564|    try {
   565|      await writeDurableJson(LEDGER_FILE, doc);
   566|      await appendDurableEvent(LEDGER_FILE, { type: 'proof_ledger_entry', ...result } as Record<string, unknown>);
   567|    } catch {
   568|      // Durable write failed — in-memory ledger still holds the entry.
   569|    }
   570|  } else {
   571|    // No Supabase service key in this runtime — persist to the GitHub side
   572|    // branch so proof survives Render's diskless deploy restarts.
   573|    await githubLedgerWrite({ ...doc, durable: true });
   574|  }
