    return ownerOnlyJson({
      ok: false,
      marker: IVX_AUTONOMOUS_CONTROL_PLANE_MARKER,
      error: error instanceof Error ? error.message : 'Unable to verify enterprise agents.',
    }, 500);
  }
}

